package com.bank.pgb;

import javax.sql.DataSource;
import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.util.logging.Logger;

public class AccountDao {
    private static final Logger log = Logger.getLogger(AccountDao.class.getName());
    private final DataSource dataSource;   // points at PgBouncer, transparently

    public AccountDao(DataSource dataSource) { this.dataSource = dataSource; }

    // One transaction = one borrowed REAL connection via PgBouncer, returned at commit.
    public BigDecimal balance(String accountId) {
        try (Connection conn = dataSource.getConnection()) {
            conn.setAutoCommit(false);              // explicit transaction
            try (PreparedStatement ps = conn.prepareStatement(
                     "SELECT balance FROM accounts WHERE id = ?")) {
                ps.setString(1, accountId);
                try (ResultSet rs = ps.executeQuery()) {
                    BigDecimal bal = rs.next() ? rs.getBigDecimal(1) : BigDecimal.ZERO;
                    conn.commit();                  // PgBouncer frees the real conn here
                    log.info(() -> "Balance " + accountId + " = Rs." + bal);
                    return bal;
                }
            }
        } catch (Exception e) {
            throw new RuntimeException("balance lookup failed", e);
        }
    }
}
