package com.bank.pgb;

import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import java.util.logging.Logger;

public class PgbDemo {
    private static final Logger log = Logger.getLogger(PgbDemo.class.getName());

    public static void main(String[] args) {
        HikariConfig cfg = new HikariConfig();
        cfg.setJdbcUrl("jdbc:postgresql://localhost:6432/bankdb"); // 6432 = PgBouncer
        cfg.setUsername("bank_app");
        cfg.setPassword("secret");
        cfg.setMaximumPoolSize(10);
        cfg.addDataSourceProperty("prepareThreshold", "0");  // transaction-pool safe
        HikariDataSource ds = new HikariDataSource(cfg);

        AccountDao dao = new AccountDao(ds);
        dao.balance("SAV2001");
        dao.balance("CUR3001");
        log.info("Thousands of clients like this share only ~40 real PostgreSQL connections.");
    }
}
